-- ULTRASTABLE-CLAIMS-1 (owner, 2026-11-10: "Always practice what you preach and implement in code always. The system shall always function as the system describes itself.")
-- (1) product_claims: each claim the Ultrastable product page makes is a row with a read-only probe. qnfo.org/platform (qnfo-gateway 3.64.0) runs the probes live;
--     the same probes are remediation contracts claim-ultrastable-<id>, run hourly, so a claim that stops being true fails its contract and is escalated like any failure mode.
-- (2) owner_asks_product_au is recreated so a changed answer is carried too (review-gate finding on PR 10156: the open-issue dedup matched any answer of the same kind,
--     so a second, different answer filed nothing). The dedup now matches the exact answer.
-- PREDICTION: remediation_verifications for class LIKE 'claim-ultrastable-%' pass share >= 0.85 within 48 h. Falsifier: a failing claim is a claim the page must drop or the fleet must fix.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE remediation_contracts SET status = 'retired' WHERE class LIKE 'claim-ultrastable-%'; DROP TABLE IF EXISTS product_claims
-- BACKUP: owner_asks
-- CAUSE-MAPPED: registers no metric.
-- spof-review: probes are single SELECTs over existing tables; qnfo-gateway refuses any probe_sql that is not one SELECT and shows a read failure as its own state.

CREATE TABLE IF NOT EXISTS product_claims (id TEXT PRIMARY KEY, product TEXT NOT NULL, sort INTEGER NOT NULL DEFAULT 50, claim TEXT NOT NULL, probe_sql TEXT NOT NULL, evidence_note TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')));
INSERT OR REPLACE INTO product_claims (id, product, sort, claim, probe_sql, evidence_note) VALUES ('own-work', 'ultrastable', 1, 'It finds its own work: issues with a code task for its code loop were filed in the last 7 days.', 'SELECT ''ok'' AS expected, CASE WHEN COUNT(*) > 0 THEN ''ok'' ELSE ''none filed in 7 days'' END AS observed, COUNT(*) || '' issues with a code-task line filed in the last 7 days'' AS detail FROM agent_issues WHERE created_at > (CAST(strftime(''%s'',''now'') AS INTEGER) - 7*86400) * 1000 AND description LIKE ''%code-task:%''', 'qnfo-audit.agent_issues');
INSERT OR REPLACE INTO product_claims (id, product, sort, claim, probe_sql, evidence_note) VALUES ('predictions-scored', 'ultrastable', 2, 'It scores its decisions: outcomes were checked against a prediction logged before the decision, in the last 7 days.', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM decision_outcomes WHERE ts > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-7 days'')) > 0 THEN ''ok'' ELSE ''no outcome scored in 7 days'' END AS observed, (SELECT COUNT(*) FROM decision_outcomes WHERE ts > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-7 days'')) || '' scored in 7 days; all time '' || (SELECT SUM(matched) FROM decision_outcomes) || '' of '' || (SELECT COUNT(*) FROM decision_outcomes) || '' matched'' AS detail', 'qnfo-audit.decision_outcomes');
INSERT OR REPLACE INTO product_claims (id, product, sort, claim, probe_sql, evidence_note) VALUES ('tick-running', 'ultrastable', 3, 'It runs continuously: the tick recorded its steps in the last 2 hours.', 'SELECT ''ok'' AS expected, CASE WHEN COUNT(*) > 0 THEN ''ok'' ELSE ''no tick step in 2 hours'' END AS observed, COUNT(*) || '' tick steps in the last 2 hours; last '' || COALESCE(MAX(ts), ''never'') AS detail FROM tick_runs WHERE ts > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'')', 'qnfo-audit.tick_runs');
INSERT OR REPLACE INTO product_claims (id, product, sort, claim, probe_sql, evidence_note) VALUES ('trust-ledger', 'ultrastable', 4, 'It keeps a trust score per kind of action, refreshed in the last 3 hours.', 'SELECT ''ok'' AS expected, CASE WHEN MAX(refreshed_at) > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-3 hours'') THEN ''ok'' ELSE ''not refreshed in 3 hours'' END AS observed, COUNT(*) || '' surface and action classes; refreshed '' || COALESCE(MAX(refreshed_at), ''never'') AS detail FROM trust_ledger', 'qnfo-audit.trust_ledger');
INSERT OR REPLACE INTO product_claims (id, product, sort, claim, probe_sql, evidence_note) VALUES ('failure-detectors', 'ultrastable', 5, 'It watches its own failure modes: every recorded failure mode family has active detectors.', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM remediation_contracts WHERE class LIKE ''fm-%'' AND status = ''active'') > 0 THEN ''ok'' ELSE ''no active detector'' END AS observed, (SELECT COUNT(*) FROM failure_modes) || '' failure modes recorded; '' || (SELECT COUNT(*) FROM remediation_contracts WHERE class LIKE ''fm-%'' AND status = ''active'') || '' active detectors'' AS detail', 'qnfo-audit.failure_modes');
INSERT OR REPLACE INTO product_claims (id, product, sort, claim, probe_sql, evidence_note) VALUES ('no-silent-drop', 'ultrastable', 6, 'It loses nothing: every issue that entered the ledger is open, closed with a disposition, or a recorded delete.', 'SELECT ''ok'' AS expected, CASE WHEN silent_drops_since_ledger = 0 AND deleted_unrecorded = 0 THEN ''ok'' ELSE silent_drops_since_ledger || '' silent drops'' END AS observed, open_n || '' open, '' || closed_with_disposition || '' closed with a disposition, '' || silent_drops_since_ledger || '' silent drops'' AS detail FROM v_issue_accounting', 'qnfo-audit.v_issue_accounting');
INSERT OR REPLACE INTO product_claims (id, product, sort, claim, probe_sql, evidence_note) VALUES ('decisions-logged', 'ultrastable', 7, 'It records its own decisions: autonomous decisions were logged with a rollback path in the last 7 days.', 'SELECT ''ok'' AS expected, CASE WHEN COUNT(*) > 0 THEN ''ok'' ELSE ''no decision logged in 7 days'' END AS observed, COUNT(*) || '' decisions logged in 7 days'' AS detail FROM decision_log WHERE ts > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-7 days'')', 'qnfo-audit.decision_log');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
SELECT 'claim-ultrastable-' || id, NULL, 'ULTRASTABLE-CLAIMS-1', 'product claim check: ' || claim, probe_sql, 'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now')
FROM product_claims WHERE product = 'ultrastable';

DROP TRIGGER IF EXISTS owner_asks_product_au;
CREATE TRIGGER IF NOT EXISTS owner_asks_product_au AFTER UPDATE OF answer ON owner_asks
WHEN NEW.kind LIKE 'product-%' AND NEW.answer IS NOT NULL AND NEW.answer != 'unsure' AND (OLD.answer IS NULL OR OLD.answer != NEW.answer)
BEGIN
  INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
  SELECT 'PRODUCT-ANSWER-1: ' || NEW.kind || ' answered "' || COALESCE(NEW.answer_label, NEW.answer) || '"',
    'The owner answered a prompted-recall question on fleet.qnfo.org/focus (owner_asks ' || NEW.id || '): ' || NEW.question || ' Answer: ' || COALESCE(NEW.answer_label, NEW.answer) || '.' || char(10) ||
    'Apply it, marked "confirmed by owner, ' || substr(COALESCE(NEW.answered_at, strftime('%Y-%m-%dT%H:%M:%SZ','now')), 1, 10) || '": rwnq8/resume docs/BRAND.md section 9 (product-name, product-buyer, product-model, product-design-credit, product-prior-sales), docs/PRODUCT-ULTRASTABLE.md here (product-name, product-buyer, product-model), and for product-design-credit the CV and site wording (rwnq8/resume RESUME.md, rwnq8/rwnq8.github.io index.html). A "no" removes the claim it asked about.' || char(10) ||
    'code-task: repo=qnfo-workers path=docs/PRODUCT-ULTRASTABLE.md' || char(10) ||
    'code-probe: {"paths": ["docs/PRODUCT-ULTRASTABLE.md"], "contains": "owner_asks ' || NEW.id || '"}',
    'owner-asks:product', 'roadmap', 'high', 'open', CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
  WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title = 'PRODUCT-ANSWER-1: ' || NEW.kind || ' answered "' || COALESCE(NEW.answer_label, NEW.answer) || '"' AND status = 'open');
END;
